INSERT INTO public.themes (title, description, image_url, display_order) VALUES ('Presidential Theme – RY 2026/27: DREAM. JOIN. PERFORM.', 'This theme carries a dual purpose: To uplift our communities and to elevate every single member of RAC TU.
INSERT INTO public.themes (title, description, image_url, display_order) VALUES ('Rotaract District Theme: Integrity, Vision, and Leadership', 'The Rotaract District 3292 theme represents a powerful triptych of core values: Integrity, Vision, and Leadership. Visually, the emblem captures this spirit through an abstract, dynamic human figure colored in striking gradients of deep pink and blue, reaching upward toward a glowing golden star. Flanked by stylized individuals waving flags, the design symbolizes collective action, youthful energy, and a shared community purpose. It serves as a visual reminder that true leadership within the district is not solitary, but rather a collaborative journey fueled by ambition and grounded in ethical values.
